{"test_code":"from billing.calendar import days_in_month, is_leap, payment_dates


def test_2100_is_not_leap() -> None:
    assert not is_leap(2100)
    assert days_in_month(2100, 2) == 28


def test_payment_dates_2100_february_clamped() -> None:
    assert payment_dates(2099, 12, 29, 4) == [
        "2099-12-29",
        "2100-01-29",
        "2100-02-28",
        "2100-03-29",
    ]
","rationale":"2100 is divisible by 100 but not 400, so it is not a leap year; the test checks days_in_month(2100, 2) is 28 and that payment_dates clamps the February 2100 payment to the 28th."}
